std::vector<Graph::Node> open_list;
std::vector<Graph::Node> closed_list;
open_list.push_back(graph.nodes[start_idx]);
while (!open_list.empty()) {
    Graph::Node current_node = *std::min_element(open_list.begin(), open_list.end(), 
        [&graph](const Graph::Node& a, const Graph::Node& b) {
            return a.g_value + graph.heuristic(a, graph.nodes[end_idx]) < b.g_value + graph.heuristic(b, graph.nodes[end_idx]);
        });
    open_list.erase(std::remove(open_list.begin(), open_list.end(), current_node), open_list.end());
    closed_list.push_back(current_node);
    if (current_node.index == end_idx) {
        std::vector<Graph::Node> path;
        while (current_node.index != start_idx) {
            path.push_back(current_node);
            current_node = *current_node.parent;
        }
        path.push_back(current_node);
        std::reverse(path.begin(), path.end());
        return path;
    }
    for (const auto& neighbor : graph.neighbors(current_node)) {
        if (std::find(closed_list.begin(), closed_list.end(), neighbor) != closed_list.end()) {
            continue;
        }
        float tentative_g_value = current_node.g_value + graph.distance(current_node, neighbor);
        if (std::find(open_list.begin(), open_list.end(), neighbor) == open_list.end()) {
            open_list.push_back(neighbor);
        } else if (tentative_g_value >= neighbor.g_value) {
            continue;
        }
        neighbor.parent = &current_node;
        neighbor.g_value = tentative_g_value;
    }
}
return {};

